import { PipelineStage, Types } from "mongoose";

import { getWithDefault } from "../../tools/env";
import { Timesplit } from "../../tools/types";
import { User } from "../schemas/user";

export const basicMatch = (
  userId: string | Types.ObjectId,
  start: Date,
  end: Date,
) => [
  {
    $match: {
      owner:
        userId instanceof Types.ObjectId ? userId : new Types.ObjectId(userId),
      blacklistedBy: { $exists: 0 },
      played_at: { $gte: start, $lt: end },
    },
  },
];

export const basicMatchUsers = (
  userIds: string[] | Types.ObjectId[],
  start: Date,
  end: Date,
) => ({
  owner: {
    $in:
      userIds[0] instanceof Types.ObjectId
        ? userIds
        : userIds.map((id) => new Types.ObjectId(id)),
  },
  blacklistedBy: { $exists: 0 },
  played_at: { $gte: start, $lt: end },
});

export const getGroupingByTimeSplit = (timeSplit: Timesplit, prefix = "") => {
  if (prefix !== "") prefix = `${prefix}.`;
  if (timeSplit === Timesplit.all) return null;
  if (timeSplit === Timesplit.year) return { year: `$${prefix}year` };
  if (timeSplit === Timesplit.week) {
    return { year: `$${prefix}year`, week: `$${prefix}week` };
  }
  if (timeSplit === Timesplit.month) {
    return { year: `$${prefix}year`, month: `$${prefix}month` };
  }
  if (timeSplit === Timesplit.day) {
    return {
      year: `$${prefix}year`,
      month: `$${prefix}month`,
      day: `$${prefix}day`,
    };
  }
  if (timeSplit === Timesplit.hour) {
    return {
      year: `$${prefix}year`,
      month: `$${prefix}month`,
      day: `$${prefix}day`,
      hour: `$${prefix}hour`,
    };
  }
  return {};
};

export const sortByTimeSplit = (
  timeSplit: Timesplit,
  prefix = "",
): PipelineStage[] => {
  if (prefix !== "") prefix = `${prefix}.`;
  if (timeSplit === Timesplit.all) return [];
  if (timeSplit === Timesplit.year) {
    return [{ $sort: { [`${prefix}year`]: 1 } }];
  }
  if (timeSplit === Timesplit.week) {
    return [{ $sort: { [`${prefix}year`]: 1, [`${prefix}week`]: 1 } }];
  }
  if (timeSplit === Timesplit.month) {
    return [{ $sort: { [`${prefix}year`]: 1, [`${prefix}month`]: 1 } }];
  }
  if (timeSplit === Timesplit.day) {
    return [
      {
        $sort: {
          [`${prefix}year`]: 1,
          [`${prefix}month`]: 1,
          [`${prefix}day`]: 1,
        },
      },
    ];
  }
  if (timeSplit === Timesplit.hour) {
    return [
      {
        $sort: {
          [`${prefix}year`]: 1,
          [`${prefix}month`]: 1,
          [`${prefix}day`]: 1,
          [`${prefix}hour`]: 1,
        },
      },
    ];
  }
  return [];
};

export const getGroupByDateProjection = (userTimezone: string | undefined) => ({
  year: {
    $year: {
      date: "$played_at",
      timezone: userTimezone ?? getWithDefault("TIMEZONE", "Europe/Paris"),
    },
  },
  month: {
    $month: {
      date: "$played_at",
      timezone: userTimezone ?? getWithDefault("TIMEZONE", "Europe/Paris"),
    },
  },
  day: {
    $dayOfMonth: {
      date: "$played_at",
      timezone: userTimezone ?? getWithDefault("TIMEZONE", "Europe/Paris"),
    },
  },
  week: {
    $week: {
      date: "$played_at",
      timezone: userTimezone ?? getWithDefault("TIMEZONE", "Europe/Paris"),
    },
  },
  hour: {
    $hour: {
      date: "$played_at",
      timezone: userTimezone ?? getWithDefault("TIMEZONE", "Europe/Paris"),
    },
  },
});

export const getTrackSumType = (user: User, idField = "$track.duration_ms") => {
  if (user.settings.metricUsed === "number") {
    return 1;
  }
  if (user.settings.metricUsed === "duration") {
    return idField;
  }
  return 1;
};

export function getTrackSortType(user: User) {
  if (user.settings.metricUsed === "number") {
    return "count";
  }
  if (user.settings.metricUsed === "duration") {
    return "duration_ms";
  }
  return "duration_ms";
}

export const lightTrackLookupPipeline = (idField = "id") => ({
  let: { id: `$${idField}` },
  pipeline: [
    { $match: { $expr: { $eq: ["$id", "$$id"] } } },
    {
      $project: {
        _id: 1,
        id: 1,
        name: 1,
        artists: 1,
        album: 1,
        images: 1,
        duration_ms: 1,
      },
    },
  ],
  from: "tracks",
  as: "track",
});

export const lightAlbumLookupPipeline = (idField = "track.album") => ({
  let: { id: `$${idField}` },
  pipeline: [
    { $match: { $expr: { $eq: ["$id", "$$id"] } } },
    { $project: { _id: 1, id: 1, name: 1, artists: 1, images: 1 } },
  ],
  from: "albums",
  as: "album",
});

export const lightArtistLookupPipeline = (
  idField = "track.artists",
  isFieldArray = true,
) => ({
  let: { id: isFieldArray ? { $first: `$${idField}` } : `$${idField}` },
  pipeline: [
    { $match: { $expr: { $eq: ["$id", "$$id"] } } },
    { $project: { _id: 1, id: 1, name: 1, images: 1, genres: 1 } },
  ],
  from: "artists",
  as: "artist",
});

export const bestArtistLookupStages = (collection: string): PipelineStage[] => {
  if (collection !== "albums") {
    const idField = collection === "artists" ? "_id" : "primaryArtistId";
    return [
      { $lookup: lightArtistLookupPipeline(idField, false) },
      { $unwind: "$artist" },
    ];
  }

  return [
    {
      $lookup: {
        ...lightArtistLookupPipeline("album.artists"),
        as: "albumArtist",
      },
    },
    {
      $lookup: {
        ...lightArtistLookupPipeline("primaryArtistId", false),
        as: "fallbackArtist",
      },
    },
    {
      $set: {
        artist: {
          $cond: [
            { $gt: [{ $size: "$albumArtist" }, 0] },
            "$albumArtist",
            "$fallbackArtist",
          ],
        },
      },
    },
    { $unset: ["albumArtist", "fallbackArtist"] },
    { $unwind: "$artist" },
  ];
};
